import {gate142,prepareFrame142,waitUntil142} from './resource-gate142.js?v=150';
import {waitForSimulation95} from './simulation-start95.js?v=97';
import {Depot,TRAIN_BAYS} from './depot86.js?v=174';
const $=id=>document.getElementById(id);let depot,selection='NM22',opening=false,generation=0,pendingSimulation95=null;
function screen(next){document.body.dataset.gameScreen=next;$('game-home').hidden=next!=='home';$('game-depot-ui').hidden=next!=='depot';$('game-environment').hidden=!['home','depot'].includes(next);$('game-loading').hidden=next!=='loading';depot?.show(next);window.dispatchEvent(new Event('resize'));}
function back(){pendingSimulation95=null;generation++;opening=false;window.pauseTrainExperience?.();if(document.body.dataset.workspace==='simulation')$('return-workshop').click();window.workshopGame?.hideMaintenance();screen('home');ensureDepot('home');$('game-home-title').focus();}
async function detail(id){if(opening)return;opening=true;selection=id;const token=++generation;screen('loading');$('game-loading-name').textContent=id.replace(/(\D+)(\d+)/,'$1-$2');$('game-loading-message').textContent='Preparando geometría, materiales y cámaras…';$('game-loading-retry').hidden=true;try{if(!window.workshopGame)await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('El taller aún no terminó de iniciar.')),10000);window.addEventListener('workshop-ready',()=>{clearTimeout(timer);resolve();},{once:true});});await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));await window.workshopGame.selectModel(id);await window.workshopGame.readyView142();if(token!==generation)return;screen('detail');$('game-detail-status').textContent='Tren seleccionado · '+$('game-loading-name').textContent;}catch(error){if(token!==generation)return;$('game-loading-message').textContent=error.message;$('game-loading-retry').hidden=false;}finally{if(token===generation)opening=false;}}
async function choose(mode){if(mode==='substations')return choose142(mode);const result=await gate142('Preparando '+({explore:'la flota',maintenance:'el taller',operator:'la cabina',automatic:'el recorrido',substations:'la subestación'}[mode]||mode),async()=>{await choose142(mode);if(mode==='explore'){await depot.load();if(TRAIN_BAYS.some(b=>!depot.items.get(b.id)?.userData.complete))throw Error('No se terminó de preparar la flota');await prepareFrame142(depot);}else if(mode==='maintenance')await window.workshopGame.readyMaintenance142();else if(['operator','automatic'].includes(mode)){await waitUntil142(()=>window.stationScene,'la vista del recorrido');await window.stationScene.ready142();}return true;});if(mode==='maintenance'&&result===true)window.metroMission117?.brief();return result;}
async function choose142(mode){if(mode==='substations'){await import('./rectifier126.js?v=181');await window.metroSubstations127.open();return;}if(mode==='explore'){window.pauseTrainExperience?.();if(document.body.dataset.workspace==='simulation')$('return-workshop').click();screen('depot');ensureDepot();return;}if(!window.workshopGame){$('game-depot-status').textContent='Preparando controles…';await waitUntil142(()=>window.workshopGame,'los controles del taller',10000);}if(['operator','automatic'].includes(mode)&&typeof window.launchTrainExperience!=='function'){const token=++generation;pendingSimulation95=mode;screen('loading');$('game-loading-name').textContent='SIMULADOR';$('game-loading-message').textContent='Cargando datos, controles y recorrido…';$('game-loading-retry').hidden=true;try{await waitForSimulation95(window);if(token!==generation)return;pendingSimulation95=null;}catch(error){if(token!==generation)return;$('game-loading-message').textContent=error.message;$('game-loading-retry').hidden=false;return;}}if(document.body.dataset.workspace==='simulation')$('return-workshop').click();screen(mode==='maintenance'?'maintenance':'simulation');const nav=document.querySelector(`.experience-nav [data-experience="${mode}"]`);nav?.click();if(mode==='maintenance'){document.body.dataset.repairView='bench';$('maintenance-hands-panel').hidden=false;$('maintenance-hands-panel').scrollIntoView({block:'start',behavior:'auto'});} }
$('game-home-menu').innerHTML=[['explore','01','Explorar la flota','Elige un tren. Descubre cada componente.'],['maintenance','02','Misiones de taller','Diagnostica. Intervén. Comprueba.'],['operator','03','Tomar los mandos','Entra en cabina y comienza el recorrido.'],['automatic','04','Observar la red','Cambia de cámara y sigue los trenes.'],['substations','05','Explorar subestaciones','Descubre sus equipos y su interior.']].map(([id,n,title,description])=>`<button data-game-mode="${id}"><span class="game-menu-number">${n}</span><span><b>${title}</b><small>${description}</small></span><i aria-hidden="true">↗</i></button>`).join('');
for(const b of document.querySelectorAll('[data-game-mode]'))b.onclick=()=>choose(b.dataset.gameMode);
$('game-train-labels').innerHTML=TRAIN_BAYS.map(bay=>`<button hidden id="train-label-${bay.id}" data-bay-label="${bay.id}">${bay.name}<small>Línea ${bay.line} · Seleccionar</small></button>`).join('');for(const b of document.querySelectorAll('[data-bay-label]')){b.onclick=()=>depot?.select(b.dataset.bayLabel);b.onpointerenter=()=>depot?.highlight(b.dataset.bayLabel);b.onpointerleave=()=>depot?.highlight(null);}$('game-depot-retry').onclick=()=>depot?depot.load():ensureDepot();$('game-home-button').onclick=back;$('game-depot-back').onclick=back;$('game-garage-return').onclick=()=>{screen('depot');ensureDepot();};$('game-loading-back').onclick=()=>{pendingSimulation95=null;generation++;opening=false;screen('depot');ensureDepot();};$('game-loading-retry').onclick=()=>pendingSimulation95?choose(pendingSimulation95):detail(selection);
for(const b of document.querySelectorAll('[data-game-view]'))b.onclick=()=>{window.workshopGame?.view(b.dataset.gameView);for(const x of document.querySelectorAll('[data-game-view]'))x.setAttribute('aria-pressed',String(x===b));};
$('game-detail-maintain').onclick=()=>choose('maintenance');$('game-detail-drive').onclick=()=>choose('operator');
// Existing controls remain reachable; they use the same navigation instead of a second state machine.
window.addEventListener('workshop-mode',e=>{if(document.body.dataset.gameScreen==='home'||document.body.dataset.gameScreen==='depot'||document.body.dataset.gameScreen==='loading')return;screen(e.detail==='maintenance'?'maintenance':'detail');});
window.addEventListener('enter-simulation',()=>screen('simulation'));
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]')&&!['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName))back();});
screen('home');ensureDepot('home'); // Fleet warms in the background; never cover the home screen during startup.
function ensureDepot(mode='depot'){if(depot){depot.show(mode);return;}try{depot=new Depot($('game-depot-canvas'),{onSelect:detail,onHover(id){for(const x of document.querySelectorAll('[data-bay-label]'))x.classList.toggle('hovered',x.dataset.bayLabel===id);},onLabels(points){for(const point of points){const label=$('train-label-'+point.id);label.hidden=!point.visible;label.style.left=point.x+'px';label.style.top=point.y+'px';}},onStatus(message,id,ok=true){$('game-depot-status').textContent=message;$('game-depot-retry').hidden=Boolean(depot?.loading)||!TRAIN_BAYS.some(bay=>!depot?.items.get(bay.id)?.userData.complete);}});depot.show(mode);depot.load();}catch(error){$('game-depot-status').textContent='No se pudo abrir el taller 3D. Reintenta la carga.';$('game-depot-retry').hidden=false;console.warn(error);}}
window.metroGame={choose,home:back,detail,get selection(){return selection;}};
